76	// Shape function for use with ops no outputs.
77	inline absl::Status NoOutputs(shape_inference::InferenceContext* c) {
78	  return absl::OkStatus();
79	}
80	
81	// Shape function for ops that output a single scalar value.
82	inline absl::Status ScalarShape(shape_inference::InferenceContext* c) {
83	  c->set_output(0, c->Scalar());
84	  return absl::OkStatus();
85	}
