87	// Shape function for binary ops where both inputs and the output match.
88	inline absl::Status MergeBothInputsShapeFn(InferenceContext* c) {
89	  ShapeHandle out;
90	  TF_RETURN_IF_ERROR(c->Merge(c->input(0), c->input(1), &out));
