46	absl::Status GetAxisForPackAndUnpack(InferenceContext* c,
47	                                     int32_t rank_after_pack, int32_t* axis) {
48	  TF_RETURN_IF_ERROR(c->GetAttr("axis", axis));
49	  if (*axis < -1 * rank_after_pack || *axis >= rank_after_pack) {
50	    return absl::InvalidArgumentError(
51	        absl::StrCat("Invalid axis: ", *axis, "; must be in [",
52	                     -1 * rank_after_pack, ",", rank_after_pack, ")"));
53	  }
54	  if (*axis < 0) *axis = (rank_after_pack + *axis);
55	  return absl::OkStatus();
56	}
