58	template <typename T>
59	std::vector<int64_t> AsInt64(const Tensor* tensor, int64_t num_elements) {
60	  std::vector<int64_t> ret(num_elements);
61	  auto data = tensor->vec<T>();
62	  for (int64_t i = 0; i < num_elements; ++i) {
63	    ret[i] = data(i);
64	  }
65	  return ret;
66	}
