68	template <typename T>
69	absl::Status PadKnown(InferenceContext* c, ShapeHandle input,
70	                      const Tensor* paddings_t, int64_t num_dims) {
71	  // paddings_t is known.
72	  std::vector<DimensionHandle> dims(num_dims);
73	  auto paddings_data = paddings_t->matrix<T>();
74	  for (int64_t i = 0; i < num_dims; ++i) {
75	    const T pad0 = paddings_data(i, 0);
76	    const T pad1 = paddings_data(i, 1);
77	    if (pad0 < 0 || pad1 < 0) {
78	      return absl::InvalidArgumentError("Paddings must be non-negative");
79	    }
80	    TF_RETURN_IF_ERROR(c->Add(c->Dim(input, i), pad0 + pad1, &dims[i]));
81	  }
82	  c->set_output(0, c->MakeShape(dims));
83	  return absl::OkStatus();
84	}
85	
86	absl::Status PadShapeFn(InferenceContext* c) {
87	  // Paddings is a matrix of [input_rank, 2].
88	  ShapeHandle paddings;
89	  TF_RETURN_IF_ERROR(c->WithRank(c->input(1), 2, &paddings));
90	  DimensionHandle unused;
91	  TF_RETURN_IF_ERROR(c->WithValue(c->Dim(paddings, 1), 2, &unused));
92	
93	  // n_dim and input.rank are equivalent.
94	  ShapeHandle input = c->input(0);
95	  DimensionHandle n_dim = c->Dim(paddings, 0);
96	  if (c->ValueKnown(n_dim)) {
97	    TF_RETURN_IF_ERROR(c->WithRank(input, c->Value(n_dim), &input));
98	  } else if (c->RankKnown(input)) {
99	    TF_RETURN_IF_ERROR(c->WithValue(n_dim, c->Rank(input), &n_dim));
100	  }
101	
102	  const Tensor* paddings_t = c->input_tensor(1);
103	
104	  // paddings_t is unknown
105	  if (paddings_t == nullptr) {
106	    if (c->ValueKnown(n_dim)) {
107	      // Make output with n_dim unknown dims.
108	      c->set_output(0, c->UnknownShapeOfRank(c->Value(n_dim)));
109	    } else {
110	      c->set_output(0, c->UnknownShape());
111	    }
112	    return absl::OkStatus();
113	  }
114	
115	  const int64_t num_dims = paddings_t->shape().dim_size(0);
116	  TF_RETURN_IF_ERROR(c->WithRank(input, num_dims, &input));
117	  TF_RETURN_IF_ERROR(c->WithValue(n_dim, num_dims, &n_dim));
118	
119	  if (paddings_t->dtype() == DT_INT32) {
120	    return PadKnown<int32_t>(c, input, paddings_t, num_dims);
121	  } else {
122	    return PadKnown<int64_t>(c, input, paddings_t, num_dims);
123	  }
124	}
