126	absl::Status TransposeShapeFn(InferenceContext* c) {
127	  ShapeHandle input = c->input(0);
128	  ShapeHandle perm_shape = c->input(1);
129	  const Tensor* perm = c->input_tensor(1);
130	  DimensionHandle perm_elems = c->NumElements(perm_shape);
131	  // If we don't have rank information on the input or value information on
132	  // perm we can't return any shape information, otherwise we have enough
133	  // information to at least find the rank of the output.
134	  if (!c->RankKnown(input) && !c->ValueKnown(perm_elems) && perm == nullptr) {
135	    c->set_output(0, c->UnknownShape());
136	    return absl::OkStatus();
137	  }
138	
139	  // Find our value of the rank.
140	  int64_t rank;
141	  if (c->RankKnown(input)) {
142	    rank = c->Rank(input);
143	  } else if (c->ValueKnown(perm_elems)) {
144	    rank = c->Value(perm_elems);
145	  } else {
146	    rank = perm->NumElements();
147	  }
148	  if (!c->RankKnown(input) && rank < 2) {
149	    // A permutation array containing a single element is ambiguous. It could
150	    // indicate either a scalar or a 1-dimensional array, both of which the
151	    // transpose op returns unchanged.
152	    c->set_output(0, input);
153	    return absl::OkStatus();
154	  }
155	
156	  std::vector<DimensionHandle> dims;
157	  dims.resize(rank);
158	  TF_RETURN_IF_ERROR(c->WithRank(input, rank, &input));
159	  // Ensure that perm is a vector and has rank elements.
160	  TF_RETURN_IF_ERROR(c->WithRank(perm_shape, 1, &perm_shape));
161	  TF_RETURN_IF_ERROR(c->WithValue(perm_elems, rank, &perm_elems));
162	
163	  // If we know the rank of the input and the value of perm, we can return
164	  // all shape information, otherwise we can only return rank information,
165	  // but no information for the dimensions.
166	  if (perm != nullptr) {
167	    std::vector<int64_t> data;
168	    if (perm->dtype() == DT_INT32) {
169	      data = AsInt64<int32_t>(perm, rank);
170	    } else {
171	      data = AsInt64<int64_t>(perm, rank);
172	    }
173	
174	    for (int32_t i = 0; i < rank; ++i) {
175	      int64_t in_idx = data[i];
176	      if (in_idx >= rank || in_idx < -rank) {
177	        return absl::InvalidArgumentError(absl::StrCat(
178	            "perm dim ", in_idx, " is out of range of input rank ", rank));
179	      }
180	      dims[i] = c->Dim(input, in_idx);
181	    }
182	  } else {
183	    for (int i = 0; i < rank; ++i) {
184	      dims[i] = c->UnknownDim();
185	    }
186	  }
187	
188	  c->set_output(0, c->MakeShape(dims));
189	  return absl::OkStatus();
190	}
