192	absl::Status SetOutputShapeForReshape(InferenceContext* c) {
193	  ShapeHandle in = c->input(0);
194	  ShapeHandle out;
195	  TF_RETURN_IF_ERROR(c->MakeShapeFromShapeTensor(1, &out));
196	
197	  if (!c->RankKnown(out)) {
198	    // We have no information about the shape of the output.
199	    c->set_output(0, out);
200	    return absl::OkStatus();
201	  }
202	  if (c->RankKnown(in)) {
203	    // We don't know the number of output elements, but we can try to infer
204	    // the missing dimension.
205	    bool too_many_unknown = false;
206	    int32_t out_unknown_idx = -1;
207	
208	    DimensionHandle known_out_elems = c->NumElements(out);
209	    if (!c->ValueKnown(known_out_elems)) {
210	      known_out_elems = c->MakeDim(1);
211	      for (int32_t i = 0; i < c->Rank(out); ++i) {
212	        DimensionHandle dim = c->Dim(out, i);
213	        if (!c->ValueKnown(dim)) {
214	          if (out_unknown_idx >= 0) {
215	            too_many_unknown = true;
216	            break;
217	          }
218	          out_unknown_idx = i;
219	        } else {
220	          TF_RETURN_IF_ERROR(
221	              c->Multiply(known_out_elems, dim, &known_out_elems));
222	        }
223	      }
224	    }
225	    int32_t in_unknown_idx = -1;
226	    DimensionHandle known_in_elems = c->NumElements(in);
227	    if (!c->ValueKnown(known_in_elems)) {
228	      known_in_elems = c->MakeDim(1);
229	      for (int32_t i = 0; i < c->Rank(in); ++i) {
230	        DimensionHandle dim = c->Dim(in, i);
231	        if (!c->ValueKnown(dim)) {
232	          if (in_unknown_idx >= 0) {
233	            too_many_unknown = true;
234	            break;
235	          }
236	          in_unknown_idx = i;
237	        } else {
238	          TF_RETURN_IF_ERROR(c->Multiply(known_in_elems, dim, &known_in_elems));
239	        }
240	      }
241	    }
242	
243	    if (!too_many_unknown) {
244	      if (in_unknown_idx < 0 && out_unknown_idx < 0) {
245	        // Just check that the dimensions match.
246	        if (c->Value(known_in_elems) != c->Value(known_out_elems)) {
247	          return absl::InvalidArgumentError(absl::StrCat(
248	              "Cannot reshape a tensor with ", c->DebugString(known_in_elems),
249	              " elements to shape ", c->DebugString(out), " (",
250	              c->DebugString(known_out_elems), " elements)"));
251	        }
252	      } else if (in_unknown_idx < 0 && out_unknown_idx >= 0 &&
253	                 c->Value(known_out_elems) > 0) {
254	        // Input fully known, infer the one missing output dim
255	        DimensionHandle inferred_dim;
256	        TF_RETURN_IF_ERROR(c->Divide(known_in_elems, c->Value(known_out_elems),
257	                                     true /* evenly_divisible */,
258	                                     &inferred_dim));
259	        TF_RETURN_IF_ERROR(
260	            c->ReplaceDim(out, out_unknown_idx, inferred_dim, &out));
261	
262	      } else if (in_unknown_idx >= 0 && out_unknown_idx < 0 &&
263	                 c->Value(known_in_elems) != 0) {
264	        // Output fully known, infer the one missing input dim
265	        DimensionHandle inferred_dim;
266	        TF_RETURN_IF_ERROR(c->Divide(known_out_elems, c->Value(known_in_elems),
267	                                     true /* evenly_divisible */,
268	                                     &inferred_dim));
269	        DimensionHandle unknown_in_dim = c->Dim(in, in_unknown_idx);
270	        TF_RETURN_IF_ERROR(
271	            c->Merge(unknown_in_dim, inferred_dim, &unknown_in_dim));
272	      } else if (in_unknown_idx >= 0 && out_unknown_idx >= 0) {
273	        // Exactly one unknown dimension in both input and output. These 2 are
274	        // equal iff the known elements are equal.
275	        if (c->Value(known_in_elems) == c->Value(known_out_elems)) {
276	          DimensionHandle unknown_in_dim = c->Dim(in, in_unknown_idx);
277	          TF_RETURN_IF_ERROR(
278	              c->ReplaceDim(out, out_unknown_idx, unknown_in_dim, &out));
279	        }
280	      }
281	    }
282	  }
283	  c->set_output(0, out);
284	  return absl::OkStatus();
285	}
