289	REGISTER_OP("ParallelConcat")
290	    .Input("values: N * T")
291	    .Output("output: T")
292	    .Attr("N: int >= 1")
293	    .Attr("T: type")
294	    .Attr("shape: shape")
295	    .SetShapeFn([](InferenceContext* c) {
296	      // Validate that the shape attr is correct.
297	      PartialTensorShape shape;
298	      TF_RETURN_IF_ERROR(c->GetAttr("shape", &shape));
299	      ShapeHandle passed_shape;
300	      TF_RETURN_IF_ERROR(
301	          c->MakeShapeFromPartialTensorShape(shape, &passed_shape));
302	      if (!c->FullyDefined(passed_shape)) {
303	        return absl::InvalidArgumentError("shape attr must be fully defined.");
304	      }
305	      ShapeHandle cur;
306	      TF_RETURN_IF_ERROR(c->ReplaceDim(
307	          passed_shape, 0, c->MakeDim(shape_inference::DimensionOrConstant(1)),
308	          &cur));
309	      for (int i = 0; i < c->num_inputs(); ++i) {
310	        if (!c->FullyDefined(c->input(i))) {
311	          return absl::InvalidArgumentError(
312	              "All input shapes must be fully defined.");
313	        }
314	        if (c->Rank(c->input(i)) < 1) {
315	          return absl::InvalidArgumentError(absl::StrCat(
316	              "The rank of all input shapes must be greater than 0, "
317	              "but input ",
318	              i, " had rank ", c->Rank(c->input(i)), "."));
319	        }
320	        DimensionHandle unused;
321	        if (!c->WithValue(c->Dim(c->input(i), 0), 1, &unused).ok()) {
322	          return absl::InvalidArgumentError(
323	              "Size of first dimension must be 1.");
324	        }
325	        TF_RETURN_WITH_CONTEXT_IF_ERROR(c->Merge(c->input(i), cur, &cur),
326	                                        "From merging shape ", i,
327	                                        " with other shapes.");
328	      }
329	
330	      c->set_output(0, passed_shape);
331	
332	      return absl::OkStatus();
333	    });
