335	REGISTER_OP("Pack")
336	    .Input("values: N * T")
337	    .Output("output: T")
338	    .Attr("N: int >= 1")
339	    .Attr("T: type")
340	    .Attr("axis: int = 0")
341	    .SetShapeFn([](InferenceContext* c) {
342	      // Validate shapes of all inputs are compatible
343	      ShapeHandle cur = c->input(c->num_inputs() - 1);
344	      for (int i = c->num_inputs() - 2; i >= 0; --i) {
345	        TF_RETURN_WITH_CONTEXT_IF_ERROR(c->Merge(c->input(i), cur, &cur),
346	                                        "From merging shape ", i,
347	                                        " with other shapes.");
348	      }
349	      if (!c->RankKnown(cur)) {
350	        c->set_output(0, c->UnknownShape());
351	        return absl::OkStatus();
352	      }
353	      // Determine the axis that will be added, converting from negative
354	      // axes to a positive point per negative indexing rules.
355	      int32_t rank = c->Rank(cur);
356	      int32_t axis;
357	      TF_RETURN_IF_ERROR(GetAxisForPackAndUnpack(c, rank + 1, &axis));
358	
359	      // Copy all dimensions over, inserting a dimension of value #inputs
360	      // at <axis>.
361	      std::vector<DimensionHandle> dims;
362	      int index = 0;
363	      while (index < axis) dims.push_back(c->Dim(cur, index++));
364	      dims.push_back(c->MakeDim(c->num_inputs()));
365	      while (index < rank) dims.push_back(c->Dim(cur, index++));
366	
367	      c->set_output(0, c->MakeShape(dims));
368	      for (int i = 0; i < c->num_inputs(); ++i) {
369	        auto* shape_and_type = c->input_handle_shapes_and_types(i);
370	        if (shape_and_type) {
371	          if (!c->RelaxOutputHandleShapesAndMergeTypes(0, *shape_and_type)) {
372	            c->set_output_handle_shapes_and_types(
373	                0, std::vector<shape_inference::ShapeAndType>({}));
374	            break;
375	          }
376	        }
377	      }
378	      return absl::OkStatus();
379	    });
