426	REGISTER_OP("Unpack")
427	    .Input("value: T")
428	    .Output("output: num * T")
429	    .Attr("num: int >= 0")
430	    .Attr("T: type")
431	    .Attr("axis: int = 0")
432	    .SetShapeFn([](InferenceContext* c) {
433	      ShapeHandle s = c->input(0);
434	      ShapeHandle out;
435	      if (c->RankKnown(s)) {
436	        // Determine the axis that will be removed, converting from negative
437	        // axes to a positive point per negative indexing rules.
438	        int32_t rank = c->Rank(s);
439	        int32_t axis;
440	        TF_RETURN_IF_ERROR(GetAxisForPackAndUnpack(c, rank, &axis));
441	
442	        // The axis dim matches the number of outputs.
443	        DimensionHandle unused;
444	        TF_RETURN_IF_ERROR(
445	            c->WithValue(c->Dim(s, axis), c->num_outputs(), &unused));
446	
447	        // Copy all dimensions, removing the <axis> dimension.
448	        std::vector<DimensionHandle> dims;
449	        for (int i = 0; i < rank; ++i) {
450	          if (i != axis) dims.push_back(c->Dim(s, i));
451	        }
452	        out = c->MakeShape(dims);
453	      } else {
454	        // All outputs are the same shape, but it's not known.
455	        out = c->UnknownShape();
456	      }
457	      for (int i = 0; i < c->num_outputs(); ++i) c->set_output(i, out);
458	      return absl::OkStatus();
459	    });
