480	REGISTER_OP("BroadcastTo")
481	    .Input("input: T")
482	    .Input("shape: Tidx")
483	    .Output("output: T")
484	    .Attr("T: type")
485	    .Attr("Tidx: {int32, int64} = DT_INT32")
486	    .SetShapeFn([](InferenceContext* c) {
487	      ShapeHandle shape_in = c->input(1);
488	      TF_RETURN_IF_ERROR(c->WithRank(shape_in, 1, &shape_in));
489	      ShapeHandle out;
490	      TF_RETURN_IF_ERROR(c->MakeShapeFromShapeTensor(1, &out));
491	      if (!c->RankKnown(out)) {
492	        // We have no information about the shape of the output.
493	        c->set_output(0, out);
494	        return absl::OkStatus();
495	      }
496	
497	      ShapeHandle in = c->input(0);
498	      if (!c->RankKnown(in)) {
499	        // We have no information about the shape of the input,
500	        // nothing to do here.
501	        c->set_output(0, out);
502	        return absl::OkStatus();
503	      }
504	      int out_rank = c->Rank(out);
505	      TF_RETURN_IF_ERROR(c->WithRankAtMost(in, out_rank, &in));
506	      int in_rank = c->Rank(in);
507	      for (int i = 0; i < in_rank; ++i) {
508	        auto in_dim = c->Dim(in, in_rank - i - 1);
509	        if (c->Value(in_dim) > 1) {
510	          // If the input dimension is greater than 1 then the output dimension
511	          // must be equal to it, since we only broadcast "from left to right".
512	          auto out_dim = c->Dim(out, out_rank - i - 1);
513	          TF_RETURN_IF_ERROR(c->Merge(in_dim, out_dim, &out_dim));
514	          TF_RETURN_IF_ERROR(
515	              c->ReplaceDim(out, out_rank - i - 1, out_dim, &out));
516	        }
517	      }
518	      c->set_output(0, out);
519	      return absl::OkStatus();
520	    });
