614	REGISTER_OP("SplitV")
615	    .Input("value: T")
616	    .Input("size_splits: Tlen")
617	    .Input("split_dim: int32")
618	    .Output("output: num_split * T")
619	    .Attr("num_split: int >= 1")
620	    .Attr("T: type")
621	    .Attr("Tlen: {int8, int32, int64} = DT_INT64")
622	    .SetShapeFn([](InferenceContext* c) {
623	      DimensionHandle split_dimension;
624	      ShapeHandle input = c->input(0);
625	      TF_RETURN_IF_ERROR(c->MakeDimForScalarInputWithNegativeIndexing(
626	          2, c->Rank(input), &split_dimension));
627	      int32_t num_outputs = c->num_outputs();
628	      int32_t rank = c->Rank(input);
629	      ShapeHandle output_shape;
630	      const Tensor* size_splits = c->input_tensor(1);
631	      if (rank == InferenceContext::kUnknownRank) {
632	        // If the rank of input tensor is unknown, then return unknown shapes.
633	        // Note that the shape of each output can be different.
634	        for (int i = 0; i < num_outputs; ++i) {
635	          c->set_output(i, c->UnknownShape());
636	        }
637	      } else if (rank == 0) {
638	        // Throw error if input is a scalar.
639	        return absl::InvalidArgumentError("Can't split scalars");
640	      } else if (size_splits == nullptr && c->ValueKnown(split_dimension)) {
641	        // If split dimension is known, but the sizes are unknown, then
642	        // only the split dimension is unknown
643	        output_shape = input;
644	        for (int i = 0; i < num_outputs; ++i) {
645	          TF_RETURN_IF_ERROR(c->ReplaceDim(output_shape,
646	                                           c->Value(split_dimension),
647	                                           c->UnknownDim(), &output_shape));
648	          c->set_output(i, output_shape);
649	        }
650	      } else if (size_splits == nullptr && !c->ValueKnown(split_dimension)) {
651	        // If split dimension or tensor containing the split sizes is unknown,
652	        // then return unknown shapes of same rank as input. Note that each
653	        // output shape can be different since splitv doesn't always split
654	        // tensors evenly.
655	        for (int i = 0; i < num_outputs; ++i) {
656	          c->set_output(i, c->UnknownShapeOfRank(rank));
657	        }
658	      } else {
659	        // Determine the output shape if split dimension and split sizes are
660	        // known.
661	        int64_t split_dim = c->Value(split_dimension);
662	        TF_RETURN_IF_ERROR(c->WithRankAtLeast(input, split_dim + 1, &input));
663	        std::vector<int64_t> data;
664	        if (size_splits->dtype() == DT_INT32) {
665	          data =
666	              AsInt64<int32_t>(size_splits, size_splits->shape().dim_size(0));
667	        } else {
668	          data =
669	              AsInt64<int64_t>(size_splits, size_splits->shape().dim_size(0));
670	        }
671	        if (num_outputs != data.size()) {
672	          return absl::InvalidArgumentError(
673	              "Length of size_splits should be equal to num_outputs");
674	        }
675	        int64_t total_size = 0;
676	        bool has_neg_one = false;
677	        for (const auto size : data) {
678	          if (size == -1) {
679	            if (has_neg_one) {
680	              return absl::InvalidArgumentError(
681	                  "size_splits can only have one -1");
682	            }
683	            has_neg_one = true;
684	          } else {
685	            total_size += size;
686	          }
687	        }
688	        auto split_dim_size = c->Value(c->Dim(input, split_dim));
689	        // If the sizes of the splits are known, then
690	        // make sure that the sizes add up to the expected
691	        // dimension size, with the possibility of a -1.
692	        // Specify the full output shapes.
693	        for (int i = 0; i < num_outputs; ++i) {
694	          auto size = data[i];
695	          if (data[i] == -1 && c->ValueKnown(split_dim_size)) {
696	            size = split_dim_size - total_size;
697	          }
698	          // If we have a negative known size (either explicit, or computed
699	          // via -1), then the split sizes are invalid.
700	          if (size < -1 || (size == -1 && c->ValueKnown(split_dim_size))) {
701	            return absl::InvalidArgumentError(absl::StrCat(
702	                "Split size at index ", i, " must be >= 0. Got: ", size));
703	          }
704	          TF_RETURN_IF_ERROR(
705	              c->ReplaceDim(input, split_dim, c->MakeDim(size), &output_shape));
706	          c->set_output(i, output_shape);
707	        }
708	        if (c->ValueKnown(split_dim_size)) {
709	          if (has_neg_one ? total_size > split_dim_size
710	                          : total_size != split_dim_size) {
711	            return absl::InvalidArgumentError(absl::StrCat(
712	                "can't split axis of size ", split_dim_size,
713	                " into pieces of size [", absl::StrJoin(data, ","), "]"));
714	          }
715	        }
716	      }
717	
718	      return absl::OkStatus();
719	    });
