814	REGISTER_OP("DiagPart")
815	    .Input("input: T")
816	    .Output("diagonal: T")
817	    .Attr(
818	        "T: {bfloat16, half, float, double, int32, int64, complex64, "
819	        "complex128}")
820	    .SetShapeFn([](InferenceContext* c) {
821	      ShapeHandle in = c->input(0);
822	      if (!c->RankKnown(in)) {
823	        c->set_output(0, c->UnknownShape());
824	        return absl::OkStatus();
825	      }
826	      // Rank must be even, and result will have rank <rank/2>.
827	      const int32_t rank = c->Rank(in);
828	      if ((rank % 2) != 0 || rank <= 0) {
829	        return absl::InvalidArgumentError(absl::StrCat(
830	            "Input must have even and non-zero rank, input rank is ", rank));
831	      }
832	      const int32_t mid = rank / 2;
