834	      // output dim[i] is the merge of in.dim[i] and in.dim[i+mid].
835	      std::vector<DimensionHandle> dims(mid);
836	      for (int i = 0; i < mid; ++i) {
837	        TF_RETURN_IF_ERROR(
838	            c->Merge(c->Dim(in, i), c->Dim(in, i + mid), &dims[i]));
839	      }
840	      c->set_output(0, c->MakeShape(dims));
841	      return absl::OkStatus();
842	    });
