1025	        "bfloat16, half, float, double, complex64, complex128, string}")
1026	    .SetShapeFn([](InferenceContext* c) {
1027	      ShapeHandle input = c->input(0);
1028	      ShapeHandle axis;
1029	      TF_RETURN_IF_ERROR(c->WithRank(c->input(1), 1, &axis));
1030	      if (c->Rank(input) > 8) {
1031	        return absl::InvalidArgumentError(
1032	            "reverse does not work on tensors with more than 8 dimensions");
1033	      }
1034	      const Tensor* axis_tensor = c->input_tensor(1);
1035	      if (axis_tensor != nullptr && c->RankKnown(input)) {
1036	        int32_t rank = c->Rank(input);
1037	        std::vector<int64_t> axis_value;
1038	        if (axis_tensor->dtype() == DT_INT32) {
1039	          axis_value =
1040	              AsInt64<int32_t>(axis_tensor, axis_tensor->NumElements());
1041	        } else {
1042	          axis_value =
1043	              AsInt64<int64_t>(axis_tensor, axis_tensor->NumElements());
1044	        }
1045	        std::vector<bool> axes_dense(c->Rank(input), false);
1046	        for (int i = 0; i < axis_value.size(); i++) {
1047	          int64_t canonical_axis =
1048	              axis_value[i] < 0 ? rank + axis_value[i] : axis_value[i];
1049	          if (canonical_axis < 0 || canonical_axis >= rank) {
1050	            return absl::InvalidArgumentError(
1051	                absl::StrCat("'axis'[", i, "] = ", axis_value[i],
1052	                             " is out of valid range [", 0, ", ", rank - 1));
1053	          }
1054	          if (axes_dense[canonical_axis]) {
1055	            return absl::InvalidArgumentError(absl::StrCat(
1056	                "axis ", canonical_axis, " specified more than once."));
1057	          }
1058	          axes_dense[canonical_axis] = true;
1059	        }
1060	      }
1061	      c->set_output(0, input);
1062	      return absl::OkStatus();
1063	    });
