1078	          c, c->input(0), c->input(1), c->input(2)));
1079	      TF_RETURN_IF_ERROR(shape_inference::ValidateSparseTensor(
1080	          c, c->input(3), c->input(4), c->input(5)));
1081	      const Tensor* hypothesis_shape_t = c->input_tensor(2);
1082	      const Tensor* truth_shape_t = c->input_tensor(5);
1083	      if (hypothesis_shape_t == nullptr || truth_shape_t == nullptr) {
1084	        // We need to know the runtime shape of the two tensors,
1085	        // or else the output shape is unknown.
1086	        return shape_inference::UnknownShape(c);
1087	      }
1088	      if (hypothesis_shape_t->NumElements() != truth_shape_t->NumElements()) {
1089	        return absl::InvalidArgumentError(absl::StrCat(
1090	            "Num elements of hypothesis_shape does not match truth_shape: ",
1091	            hypothesis_shape_t->NumElements(), " vs. ",
1092	            truth_shape_t->NumElements()));
1093	      }
1094	      if (hypothesis_shape_t->NumElements() < 2) {
1095	        return absl::InvalidArgumentError(absl::StrCat(
1096	            "Input Hypothesis SparseTensors must have rank at least 2, but "
1097	            "hypothesis_shape rank is: ",
1098	            hypothesis_shape_t->NumElements()));
1099	      }
1100	      if (truth_shape_t->NumElements() < 2) {
1101	        return absl::InvalidArgumentError(absl::StrCat(
1102	            "Input Truth SparseTensors must have rank at least 2, but "
1103	            "truth_shape rank is: ",
1104	            truth_shape_t->NumElements()));
1105	      }
1106	
1107	      auto h_values = hypothesis_shape_t->flat<int64_t>();
1108	      auto t_values = truth_shape_t->flat<int64_t>();
1109	      std::vector<DimensionHandle> dims(hypothesis_shape_t->NumElements() - 1);
1110	      for (int i = 0; i < dims.size(); ++i) {
1111	        dims[i] = c->MakeDim(std::max(h_values(i), t_values(i)));
1112	      }
1113	
1114	      c->set_output(0, c->MakeShape(dims));
1115	      return absl::OkStatus();
1116	    });
