1200	REGISTER_OP("Gather")
1201	    .Input("params: Tparams")
1202	    .Input("indices: Tindices")
1203	    .Attr("validate_indices: bool = true")
1204	    .Output("output: Tparams")
1205	    .Attr("Tparams: type")
1206	    .Attr("Tindices: {int32,int64}")
1207	    .SetShapeFn([](InferenceContext* c) {
1208	      ShapeHandle unused;
1209	      TF_RETURN_IF_ERROR(c->WithRankAtLeast(c->input(0), 1, &unused));
1210	      ShapeHandle params_subshape;
1211	      TF_RETURN_IF_ERROR(c->Subshape(c->input(0), 1, &params_subshape));
1212	      ShapeHandle indices_shape = c->input(1);
1213	      ShapeHandle out;
1214	      TF_RETURN_IF_ERROR(c->Concatenate(indices_shape, params_subshape, &out));
1215	      c->set_output(0, out);
1216	      return absl::OkStatus();
1217	    });
