1220	REGISTER_OP("GatherV2")
1221	    .Input("params: Tparams")
1222	    .Input("indices: Tindices")
1223	    .Input("axis: Taxis")
1224	    .Attr("batch_dims: int = 0")
1225	    .Output("output: Tparams")
1226	    .Attr("Tparams: type")
1227	    .Attr("Tindices: {int16, int32,int64}")
1228	    .Attr("Taxis: {int32,int64}")
1229	    .SetShapeFn([](InferenceContext* c) {
1230	      ShapeHandle params_shape;
1231	      TF_RETURN_IF_ERROR(c->WithRankAtLeast(c->input(0), 1, &params_shape));
1232	
1233	      ShapeHandle indices_shape = c->input(1);
1234	      ShapeHandle unused_axis_shape;
1235	      TF_RETURN_IF_ERROR(c->WithRank(c->input(2), 0, &unused_axis_shape));
1236	      const Tensor* axis_t = c->input_tensor(2);
1237	
1238	      // If axis is unknown, we can only infer that the result is params_rank +
1239	      // indices_rank - 1.
1240	      if (axis_t == nullptr) {
1241	        if (c->RankKnown(params_shape) && c->RankKnown(indices_shape)) {
1242	          int32_t batch_dims;
1243	          TF_RETURN_IF_ERROR(c->GetAttr("batch_dims", &batch_dims));
1244	          c->set_output(0, c->UnknownShapeOfRank(c->Rank(params_shape) +
1245	                                                 c->Rank(indices_shape) - 1 -
1246	                                                 batch_dims));
1247	        } else {
1248	          c->set_output(0, c->UnknownShape());
1249	        }
1250	        return absl::OkStatus();
1251	      }
1252	
1253	      // Note, axis can be negative.
1254	      int64_t axis = 0;
1255	      if (axis_t->dtype() == DT_INT32) {
1256	        axis = axis_t->scalar<int32_t>()();
1257	      } else {
1258	        axis = axis_t->scalar<int64_t>()();
1259	      }
1260	
1261	      // Check that params has rank of at least axis + 1.
1262	      ShapeHandle unused;
1263	      TF_RETURN_IF_ERROR(c->WithRankAtLeast(
1264	          params_shape, axis < 0 ? -axis : axis + 1, &unused));
1265	
1266	      // Note, batch_dims can be negative.
1267	      int32_t batch_dims;
1268	      TF_RETURN_IF_ERROR(c->GetAttr("batch_dims", &batch_dims));
1269	      // -rank(indices) <= batch_dims <= rank(indices)
1270	      TF_RETURN_IF_ERROR(
1271	          c->WithRankAtLeast(indices_shape, std::abs(batch_dims), &unused));
1272	      if (batch_dims < 0) {
1273	        batch_dims += c->Rank(indices_shape);
1274	      }
1275	      // rank(params) > batch_dims
1276	      TF_RETURN_IF_ERROR(
1277	          c->WithRankAtLeast(params_shape, batch_dims + 1, &unused));
1278	
1279	      ShapeHandle params_outer_subshape;
1280	      TF_RETURN_IF_ERROR(
1281	          c->Subshape(params_shape, 0, axis, &params_outer_subshape));
1282	
1283	      ShapeHandle indices_inner_subshape;
1284	      TF_RETURN_IF_ERROR(
1285	          c->Subshape(indices_shape, batch_dims, &indices_inner_subshape));
1286	
1287	      ShapeHandle out;
1288	      TF_RETURN_IF_ERROR(
1289	          c->Concatenate(params_outer_subshape, indices_inner_subshape, &out));
1290	
1291	      // Slice from axis + 1 to the end of params_shape to collect the inner
1292	      // dimensions of the result. Special case -1 here since -1 + 1 wraps, and
1293	      // we slice from 0 to the end of shape. Subshape() handles all other
1294	      // out-of-bounds checking.
1295	      if (axis != -1) {
1296	        ShapeHandle params_inner_subshape;
1297	        TF_RETURN_IF_ERROR(
1298	            c->Subshape(params_shape, axis + 1, &params_inner_subshape));
1299	        TF_RETURN_IF_ERROR(c->Concatenate(out, params_inner_subshape, &out));
1300	      }
1301	
1302	      c->set_output(0, out);
1303	      return absl::OkStatus();
1304	    });
