1466	namespace {
1467	absl::Status UniqueIdxShapeFn(InferenceContext* c) {
1468	  ShapeHandle input = c->input(0);
1469	  const Tensor* axis_t = c->input_tensor(1);
1470	  if (axis_t == nullptr || !c->RankKnown(input)) {
1471	    c->set_output(1, c->Vector(InferenceContext::kUnknownDim));
1472	    return absl::OkStatus();
1473	  }
1474	
1475	  if (c->Rank(c->input(1)) != 1) {
1476	    return absl::InvalidArgumentError("axis expects a 1D vector.");
1477	  }
1478	
1479	  int32_t n = axis_t->NumElements();
1480	  if (n == 0) {
1481	    if (c->Rank(input) != 1) {
1482	      return absl::InvalidArgumentError("x expects a 1D vector.");
1483	    }
1484	    c->set_output(1, input);
1485	    return absl::OkStatus();
1486	  } else if (n == 1) {
1487	    int64_t axis;
1488	    if (axis_t->dtype() == DT_INT32) {
1489	      axis = static_cast<int64_t>(axis_t->flat<int32_t>()(0));
1490	    } else {
1491	      axis = axis_t->flat<int64_t>()(0);
1492	    }
1493	
1494	    int64_t input_rank = c->Rank(input);
1495	    if (axis < -input_rank || axis >= input_rank) {
1496	      return absl::InvalidArgumentError(
1497	          absl::StrCat("axis expects to be in the range [", -input_rank, ", ",
1498	                       input_rank, ")"));
1499	    }
1500	    if (axis < 0) {
1501	      axis += input_rank;
1502	    }
1503	    c->set_output(1, c->Vector(c->Dim(input, axis)));
1504	    return absl::OkStatus();
1505	  }
1506	  return absl::InvalidArgumentError(
1507	      "axis does not support input tensors larger than 1 elements.");
1508	}
