1606	    .Input("input: T")
1607	    .Output("output: T")
1608	    .Attr("shape: shape")
1609	    .Attr("T: type")
1610	    .SetShapeFn([](InferenceContext* c) {
1611	      // Merges desired shape and statically known shape of input
1612	      PartialTensorShape desired_shape;
1613	      TF_RETURN_IF_ERROR(c->GetAttr("shape", &desired_shape));
1614	
1615	      int rank = desired_shape.dims();
1616	      ShapeHandle input_shape_handle;
1617	      ShapeHandle desired_shape_handle;
