1630	REGISTER_OP("ReverseSequence")
1631	    .Input("input: T")
1632	    .Input("seq_lengths: Tlen")
1633	    .Output("output: T")
1634	    .Attr("seq_dim: int")
1635	    .Attr("batch_dim: int = 0")
1636	    .Attr("T: type")
1637	    .Attr("Tlen: {int32, int64} = DT_INT64")
1638	    .SetShapeFn([](InferenceContext* c) {
1639	      ShapeHandle input = c->input(0);
1640	      ShapeHandle seq_lens_shape;
1641	      TF_RETURN_IF_ERROR(c->WithRank(c->input(1), 1, &seq_lens_shape));
1642	
1643	      int64_t seq_dim;
1644	      TF_RETURN_IF_ERROR(c->GetAttr("seq_dim", &seq_dim));
1645	      int64_t batch_dim;
1646	      TF_RETURN_IF_ERROR(c->GetAttr("batch_dim", &batch_dim));
1647	
1648	      if (!c->RankKnown(input)) {
1649	        return shape_inference::UnknownShape(c);
1650	      }
1651	
1652	      // Validate batch_dim and seq_dim against input.
1653	      const int32_t input_rank = c->Rank(input);
1654	      if (batch_dim >= input_rank) {
1655	        return absl::InvalidArgumentError(
1656	            absl::StrCat("batch_dim must be < input rank: ", batch_dim, " vs. ",
1657	                         input_rank));
1658	      }
1659	
1660	      if (seq_dim >= input_rank) {
1661	        return absl::InvalidArgumentError(absl::StrCat(
1662	            "seq_dim must be < input rank: ", seq_dim, " vs. ", input_rank));
1663	      }
1664	
1665	      // To prevent out of bound access when calling c->Dim(input, batch_dim),
1666	      // batch_dim range [-1 * input rank, input rank) is allowed. However,
1667	      // the op implementation has a stricter bound for batch_dim requiring >= 0
1668	      // value. Thus, perform strict check here.
1669	      if (batch_dim < 0) {
1670	        return absl::InvalidArgumentError(
1671	            absl::StrCat("batch_dim must be >=0, got ", batch_dim));
1672	      }
1673	
1674	      DimensionHandle batch_dim_dim = c->Dim(input, batch_dim);
1675	      TF_RETURN_IF_ERROR(
1676	          c->Merge(batch_dim_dim, c->Dim(seq_lens_shape, 0), &batch_dim_dim));
1677	
1678	      // Replace batch_dim of input with batch_size
1679	      ShapeHandle output_shape;
1680	      TF_RETURN_IF_ERROR(
1681	          c->ReplaceDim(input, batch_dim, batch_dim_dim, &output_shape));
1682	      c->set_output(0, output_shape);
1683	      return absl::OkStatus();
1684	    });
