1711	REGISTER_OP("StridedSlice")
1712	    .Input("input: T")
1713	    .Input("begin: Index")
1714	    .Input("end: Index")
1715	    .Input("strides: Index")
1716	    .Output("output: T")
1717	    .Attr("T: type")
1718	    .Attr("Index: {int16, int32, int64}")
1719	    .Attr("begin_mask: int = 0")
1720	    .Attr("end_mask: int = 0")
1721	    .Attr("ellipsis_mask: int = 0")
1722	    .Attr("new_axis_mask: int = 0")
1723	    .Attr("shrink_axis_mask: int = 0")
1724	    .SetShapeFn([](InferenceContext* c) {
1725	      ShapeHandle input = c->input(0);
1726	      ShapeHandle begin_shape, end_shape, strides_shape;
1727	      TF_RETURN_IF_ERROR(c->WithRank(c->input(1), 1, &begin_shape));
1728	      TF_RETURN_IF_ERROR(c->WithRank(c->input(2), 1, &end_shape));
1729	      TF_RETURN_IF_ERROR(c->WithRank(c->input(3), 1, &strides_shape));
1730	      TF_RETURN_IF_ERROR(c->Merge(begin_shape, end_shape, &begin_shape));
1731	      TF_RETURN_IF_ERROR(c->Merge(begin_shape, strides_shape, &begin_shape));
1732	      DimensionHandle sparse_dims_dim = c->Dim(begin_shape, 0);
1733	
1734	      const Tensor* strides_value = c->input_tensor(3);
1735	      // TODO(aselle,allenl): If we had a stride_mask it would be possible to do
1736	      // more shape inference here (e.g. for x[3, ::T]).
1737	      if (!c->RankKnown(input) || !c->ValueKnown(sparse_dims_dim) ||
1738	          strides_value == nullptr) {
1739	        c->set_output(0, c->UnknownShape());
1740	        return absl::OkStatus();
1741	      }
1742	
1743	      PartialTensorShape input_shape({});
1744	      for (int i = 0; i < c->Rank(input); ++i) {
1745	        auto dim = c->Dim(input, i);
1746	        input_shape.AddDim(c->ValueKnown(dim) ? c->Value(dim) : -1);
1747	      }
1748	
1749	      int32_t begin_mask, end_mask, ellipsis_mask, new_axis_mask,
1750	          shrink_axis_mask;
1751	      TF_RETURN_IF_ERROR(c->GetAttr("begin_mask", &begin_mask));
1752	      TF_RETURN_IF_ERROR(c->GetAttr("end_mask", &end_mask));
1753	      TF_RETURN_IF_ERROR(c->GetAttr("ellipsis_mask", &ellipsis_mask));
1754	      TF_RETURN_IF_ERROR(c->GetAttr("new_axis_mask", &new_axis_mask));
1755	      TF_RETURN_IF_ERROR(c->GetAttr("shrink_axis_mask", &shrink_axis_mask));
1756	
1757	      const Tensor* begin_value = c->input_tensor(1);
1758	      const Tensor* end_value = c->input_tensor(2);
1759	
1760	      PartialTensorShape processing_shape, final_shape;
1761	      bool is_identity, is_simple_slice, slice_dim0;
1762	      absl::InlinedVector<int64_t, 4UL> begin, end, strides;
1763	      TF_RETURN_IF_ERROR(ValidateStridedSliceOp(
1764	          begin_value, end_value, *strides_value, input_shape, begin_mask,
1765	          end_mask, ellipsis_mask, new_axis_mask, shrink_axis_mask,
1766	          &processing_shape, &final_shape, &is_identity, &is_simple_slice,
1767	          &slice_dim0, &begin, &end, &strides));
1768	
1769	      ShapeHandle out;
1770	      TF_RETURN_IF_ERROR(c->MakeShapeFromPartialTensorShape(final_shape, &out));
1771	      c->set_output(0, out);
1772	
1773	      auto* shape_and_type = c->input_handle_shapes_and_types(0);
1774	      if (shape_and_type) {
1775	        c->set_output_handle_shapes_and_types(0, *shape_and_type);
1776	      }
1777	
1778	      return absl::OkStatus();
1779	    });
