1980	namespace {
1981	template <typename T>
1982	absl::Status MirrorPadKnown(InferenceContext* c, ShapeHandle input,
1983	                            const Tensor* paddings_t, int64_t input_rank) {
1984	  auto paddings_data = paddings_t->matrix<T>();
1985	  std::vector<DimensionHandle> dims(input_rank);
1986	  for (int64_t i = 0; i < input_rank; ++i) {
1987	    const int64_t pad0 = static_cast<int64_t>(paddings_data(i, 0));
1988	    const int64_t pad1 = static_cast<int64_t>(paddings_data(i, 1));
1989	    if (pad0 < 0 || pad1 < 0) {
1990	      return absl::InvalidArgumentError("Paddings must be non-negative");
1991	    }
1992	
1993	    TF_RETURN_IF_ERROR(c->Subtract(c->Dim(input, i), pad0 + pad1, &dims[i]));
1994	  }
1995	  c->set_output(0, c->MakeShape(dims));
1996	  return absl::OkStatus();
1997	}
1998	
1999	}  // namespace
