2001	REGISTER_OP("MirrorPadGrad")
2002	    .Input("input: T")
2003	    .Input("paddings: Tpaddings")
2004	    .Output("output: T")
2005	    .Attr("T: type")
2006	    .Attr("Tpaddings: {int32, int64} = DT_INT32")
2007	    .Attr(GetMirrorPadModeAttrString())
2008	    .SetShapeFn([](InferenceContext* c) {
2009	      ShapeHandle paddings;
2010	      TF_RETURN_IF_ERROR(c->WithRank(c->input(1), 2, &paddings));
2011	      DimensionHandle pad_0 = c->Dim(paddings, 0);
2012	      if (!c->ValueKnown(pad_0)) {
2013	        // We don't know the rank of the output since the first
2014	        // padding dimension is unknown.
2015	        c->set_output(0, c->UnknownShape());
2016	        return absl::OkStatus();
2017	      }
2018	
2019	      int64_t input_rank = c->Value(pad_0);
2020	      ShapeHandle input;
2021	      TF_RETURN_IF_ERROR(c->WithRank(c->input(0), input_rank, &input));
2022	      TF_RETURN_IF_ERROR(
2023	          c->Merge(paddings, c->Matrix(input_rank, 2), &paddings));
2024	
2025	      const Tensor* paddings_t = c->input_tensor(1);
2026	      if (paddings_t == nullptr) {
2027	        // Values of 'paddings' is not available, but we know the
2028	        // input rank, so return the rank of the output with unknown
2029	        // dimensions.
2030	        c->set_output(0, c->UnknownShapeOfRank(input_rank));
2031	        return absl::OkStatus();
2032	      }
2033	
2034	      if (paddings_t->dtype() == DT_INT32) {
2035	        return MirrorPadKnown<int32_t>(c, input, paddings_t, input_rank);
2036	      } else {
2037	        return MirrorPadKnown<int64_t>(c, input, paddings_t, input_rank);
2038	      }
2039	    });
