2095	REGISTER_OP("ExpandDims")
2096	    .Input("input: T")
2097	    .Input("dim: Tdim")
2098	    .Output("output: T")
2099	    .Attr("T: type")
2100	    .Attr("Tdim: {int32, int64} = DT_INT32")
2101	    .SetShapeFn([](InferenceContext* c) {
2102	      ShapeHandle input = c->input(0);
2103	
2104	      const Tensor* dim_t = c->input_tensor(1);
2105	      if (dim_t != nullptr && dim_t->NumElements() != 1) {
2106	        return absl::InvalidArgumentError(
2107	            "'dim' input must be a tensor with a single value");
2108	      }
2109	      if (dim_t == nullptr || !c->RankKnown(input)) {
2110	        c->set_output(0, c->UnknownShape());
2111	        return absl::OkStatus();
2112	      }
2113	
2114	      int64_t dim;
2115	      if (dim_t->dtype() == DT_INT32) {
2116	        dim = static_cast<int64_t>(dim_t->flat<int32_t>()(0));
2117	      } else {
2118	        dim = dim_t->flat<int64_t>()(0);
2119	      }
2120	
2121	      const int32_t rank = c->Rank(input);
2122	      const int32_t min_dim = -1 * rank - 1;
2123	      if (dim < min_dim || dim > rank) {
2124	        return absl::InvalidArgumentError(absl::StrCat(
2125	            "dim ", dim, " not in the interval [", min_dim, ", ", rank, "]."));
2126	      }
2127	
2128	      if (dim < 0) {
2129	        dim += rank + 1;
2130	      }
2131	
2132	      ShapeHandle end;
2133	      TF_RETURN_IF_ERROR(c->Subshape(input, dim, &end));
2134	
2135	      // Build output as start + 1 + end.
2136	      ShapeHandle output;
2137	      TF_RETURN_IF_ERROR(c->Subshape(input, 0, dim, &output));
2138	      TF_RETURN_IF_ERROR(c->Concatenate(output, c->Vector(1), &output));
2139	      TF_RETURN_IF_ERROR(c->Concatenate(output, end, &output));
2140	      c->set_output(0, output);
2141	      return absl::OkStatus();
2142	    });
