2598	REGISTER_OP("ExtractImagePatches")
2599	    .Input("images: T")
2600	    .Output("patches: T")
2601	    .Attr("ksizes: list(int) >= 4")
2602	    .Attr("strides: list(int) >= 4")
2603	    .Attr("rates: list(int) >= 4")
2604	    .Attr(
2605	        "T: {bfloat16, half, float, double, int8, int16, int32, int64, "
2606	        "uint8, uint16, uint32, uint64, complex64, complex128, bool}")
2607	    .Attr(GetPaddingAttrString())
2608	    .SetShapeFn([](InferenceContext* c) {
2609	      ShapeHandle input_shape;
2610	      TF_RETURN_IF_ERROR(c->WithRank(c->input(0), 4, &input_shape));
2611	
2612	      std::vector<int32_t> ksizes;
2613	      TF_RETURN_IF_ERROR(c->GetAttr("ksizes", &ksizes));
2614	      if (ksizes.size() != 4) {
2615	        return absl::InvalidArgumentError(absl::StrCat(
2616	            "ExtractImagePatches requires the ksizes attribute to contain 4 "
2617	            "values, but got: ",
2618	            ksizes.size()));
2619	      }
2620	
2621	      std::vector<int32_t> strides;
2622	      TF_RETURN_IF_ERROR(c->GetAttr("strides", &strides));
2623	      if (strides.size() != 4) {
2624	        return absl::InvalidArgumentError(absl::StrCat(
2625	            "ExtractImagePatches requires the stride attribute to contain 4 "
2626	            "values, but got: ",
2627	            strides.size()));
2628	      }
2629	
2630	      std::vector<int32_t> rates;
2631	      TF_RETURN_IF_ERROR(c->GetAttr("rates", &rates));
2632	      if (rates.size() != 4) {
2633	        return absl::InvalidArgumentError(absl::StrCat(
2634	            "ExtractImagePatches requires the rates attribute to contain 4 "
2635	            "values, but got: ",
2636	            rates.size()));
2637	      }
2638	
2639	      int32_t ksize_rows = ksizes[1];
2640	      int32_t ksize_cols = ksizes[2];
2641	
2642	      int32_t stride_rows = strides[1];
2643	      int32_t stride_cols = strides[2];
2644	
2645	      int32_t rate_rows = rates[1];
2646	      int32_t rate_cols = rates[2];
2647	
2648	      int32_t ksize_rows_eff = ksize_rows + (ksize_rows - 1) * (rate_rows - 1);
2649	      int32_t ksize_cols_eff = ksize_cols + (ksize_cols - 1) * (rate_cols - 1);
2650	
2651	      DimensionHandle batch_size_dim = c->Dim(input_shape, 0);
2652	      DimensionHandle in_rows_dim = c->Dim(input_shape, 1);
2653	      DimensionHandle in_cols_dim = c->Dim(input_shape, 2);
2654	      DimensionHandle output_depth_dim;
2655	      TF_RETURN_IF_ERROR(c->Multiply(
2656	          c->Dim(input_shape, 3), ksize_rows * ksize_cols, &output_depth_dim));
2657	
2658	      if (!c->ValueKnown(in_rows_dim) || !c->ValueKnown(in_cols_dim)) {
2659	        ShapeHandle output_shape =
2660	            c->MakeShape({batch_size_dim, InferenceContext::kUnknownDim,
2661	                          InferenceContext::kUnknownDim, output_depth_dim});
2662	        c->set_output(0, output_shape);
2663	        return absl::OkStatus();
2664	      }
2665	      auto in_rows = c->Value(in_rows_dim);
2666	      auto in_cols = c->Value(in_cols_dim);
2667	
2668	      Padding padding;
2669	      TF_RETURN_IF_ERROR(c->GetAttr("padding", &padding));
2670	
2671	      int64_t output_rows, output_cols;
2672	      int64_t padding_before, padding_after;
2673	      TF_RETURN_IF_ERROR(GetWindowedOutputSizeVerbose(
2674	          in_rows, ksize_rows_eff, /*dilation_rate=*/1, stride_rows, padding,
2675	          &output_rows, &padding_before, &padding_after));
2676	      TF_RETURN_IF_ERROR(GetWindowedOutputSizeVerbose(
2677	          in_cols, ksize_cols_eff, /*dilation_rate=*/1, stride_cols, padding,
2678	          &output_cols, &padding_before, &padding_after));
2679	      ShapeHandle output_shape = c->MakeShape(
2680	          {batch_size_dim, output_rows, output_cols, output_depth_dim});
2681	      c->set_output(0, output_shape);
2682	      return absl::OkStatus();
2683	    });
