2797	REGISTER_OP("OneHot")
2798	    .Input("indices: TI")
2799	    .Input("depth: int32")
2800	    .Input("on_value: T")
2801	    .Input("off_value: T")
2802	    .Attr("axis: int = -1")
2803	    .Output("output: T")
2804	    .Attr("T: type")
2805	    .Attr("TI: {uint8, int8, int32, int64} = DT_INT64")
2806	    .SetShapeFn([](InferenceContext* c) {
2807	      int32_t axis;
2808	      TF_RETURN_IF_ERROR(c->GetAttr("axis", &axis));
2809	      if (axis < -1) return absl::InvalidArgumentError("axis must be >= -1");
2810	
2811	      DimensionHandle depth;
2812	      TF_RETURN_IF_ERROR(c->MakeDimForScalarInput(1, &depth));
2813	
2814	      ShapeHandle indices = c->input(0);
2815	      if (!c->RankKnown(indices)) return shape_inference::UnknownShape(c);
2816	
2817	      int32_t new_rank = c->Rank(indices) + 1;
2818	      // We need to add new_rank to axis in the case the axis is -1 because
2819	      // C++ returns negative values from % if the dividend is negative.
2820	      int32_t depth_index = (axis + new_rank) % new_rank;
2821	      // Out shape is indices[0:depth_index] + [depth] + indices[depth_index:].
2822	      ShapeHandle front;
2823	      ShapeHandle back;
2824	      ShapeHandle out;
2825	      TF_RETURN_IF_ERROR(c->Subshape(indices, 0, depth_index, &front));
2826	      TF_RETURN_IF_ERROR(c->Subshape(indices, depth_index, &back));
2827	      TF_RETURN_IF_ERROR(c->Concatenate(front, c->Vector(depth), &front));
2828	      TF_RETURN_IF_ERROR(c->Concatenate(front, back, &out));
2829	      c->set_output(0, out);
2830	      return absl::OkStatus();
2831	    });
