3030	      int axis = -1;
3031	      absl::Status s = c->GetAttr("axis", &axis);
3032	      if (!s.ok() && s.code() != error::NOT_FOUND) {
3033	        return s;
3034	      }
3035	      if (axis < -1) {
3036	        return absl::InvalidArgumentError(
3037	            absl::StrCat("axis should be at least -1, got ", axis));
3038	      }
3039	      auto input_dims = c->Rank(c->input(0));
3040	      if (axis > input_dims) {
3041	        return absl::InvalidArgumentError(
3042	            absl::StrCat("Axis must be less than input dimension(", input_dims,
3043	                         "), got ", axis));
3044	      }
