224	// Shape inference functions registered on ops in REGISTER_OP implement
225	// their shape functions in terms of this InferenceContext.  An InferenceContext
226	// is created by the framework and passed to a shape inference function.  The
227	// shape inference function calls functions on the context, and should call
228	// set_output() to set the shape on all outputs.
229	//
230	// To infer shapes for user-defined functions see ShapeRefiner.
231	//
232	// All Shape* and Dimension* returned by functions of InferenceContext are owned
233	// by the InferenceContext.
234	class InferenceContext {
235	 public:
236	  static constexpr int64_t kUnknownDim = -1;
237	  static constexpr int32_t kUnknownRank = -1;
238	
239	  // <input_tensors> is NULL-padded to be the same size as <input_shapes>.
240	  //
241	  // Elements of <input_tensors_as_shapes> are used for when a shape function
242	  // makes a call to MakeShapeFromShapeTensor; in particular, when the
243	  // input_tensors[i] is nullptr but the shape represented by it is partially
244	  // known from analysis of the graph.
245	  // <input_tensors_as_shapes> can have fewer elements than <input_shapes>.
246	  // Values of <input_tensors_as_shapes> do not need to outlive the context.
247	  InferenceContext(int graph_def_version, const AttrSlice& attrs,
248	                   const OpDef& op_def,
249	                   const std::vector<ShapeHandle>& input_shapes,
250	                   const std::vector<const Tensor*>& input_tensors,
251	                   const std::vector<ShapeHandle>& input_tensors_as_shapes,
252	                   std::vector<std::unique_ptr<std::vector<ShapeAndType>>>
253	                       input_handle_shapes_and_types);
254	
255	  // <input_tensors> is NULL-padded to be the same size as <input_shapes>.
256	  //
257	  // Elements of <input_tensors_as_shapes> are used for when a shape
258	  // function makes a call to MakeShapeFromShapeTensor; in particular, when
259	  // the input_tensors[i] is nullptr but the shape represented by it is
260	  // partially known from analysis of the graph. <input_tensors_as_shapes>
261	  // can have fewer elements than <input_shapes>. Values of
262	  // <input_tensors_as_shapes> do not need to outlive the context.
263	  InferenceContext(
264	      int graph_def_version, const AttrSlice& attrs, const OpDef& op_def,
265	      const std::vector<PartialTensorShape>& input_shapes,
266	      const std::vector<const Tensor*>& input_tensors,
267	      const std::vector<PartialTensorShape>& input_tensors_as_shapes,
268	      const std::vector<std::unique_ptr<
269	          std::vector<std::pair<PartialTensorShape, DataType>>>>&
270	          input_handle_shapes_and_types);
271	
272	  ~InferenceContext();
273	
274	  // Runs the shape inference function 'fn' with 'this' as the
275	  // argument, returns the status of the inference.
276	  //
277	  // On error, additional context is provided in the error message.
278	  absl::Status Run(
279	      const std::function<absl::Status(shape_inference::InferenceContext* c)>&
280	          fn);
281	
282	  // Merge the stored shape of the input in position idx with <shape> according
283	  // to the following rules:
284	  //
285	  // - If the ShapeHandles are the same or <shape> is unknown, there will be no
286	  //   change. Otherwise if the stored shape is unknown, the new shape will be
287	  //   <shape>.
288	  // - If both shapes are known, then they must have the same rank.
289	  // - For any one dimension, if the values for that dimension in both shapes
290	  //   are known, then the values must match.
291	  // - If one shape has equal or more information than the other shape in every
292	  //   dimension, the new shape will become the shape with more information.
293	  // - Example: merging [2,?] and [?,2] results in [2,2]
294	  // - Example: [2,2] cannot be merged with [1,2]
295	  //
296	  // This requires idx to be in the [0, num_inputs) range. If the merge is
297	  // successful, return true. Return false otherwise.
298	  bool MergeInput(int idx, ShapeHandle shape) {
299	    if (idx < 0 || idx >= num_inputs()) return false;
300	    ShapeHandle new_shape;
301	    if (!Merge(inputs_[idx], shape, &new_shape).ok()) return false;
302	    inputs_[idx] = new_shape;
303	    return true;
304	  }
305	
306	  // Relax the stored shape of the input in position idx with <shape> according
307	  // to the following rules:
308	  //
309	  // - If the ShapeHandles are the same then the stored shape will be returned.
310	  // - If either of the ShapeHandles are unknown, then a new UnknownShape will
311	  //   be returned. A new shape must be returned because we cannot claim that
312	  //   the resulting shape is necessarily the same as either of the input
313	  //   shapes.
314	  // - If the shapes both have known ranks but their ranks are different, a new
315	  //   UnknownShape will be returned.
316	  // - For any one dimension, if the value for that dimension in either of the
317	  //   shapes is unknown, a new shape will be returned with a new UnknownDim in
318	  //   that dimension.
319	  // - For any one dimension, if the values for that dimension in both shapes
320	  //   are known but do not match, a new shape will be returned with a new
321	  //   UnknownDim in that dimension.
322	  // - If both shapes have the same known rank and match in every dimension,
323	  //   the stored shape will be returned.
324	  // - Example: relaxing [2,?] and [?,2] results in [?,?]
325	  // - Example: relaxing [2,2] and [3,2] results in [?,2]
326	  // - Example: relaxing [2,2] with [1,2,3] results in ?
327	  //
328	  // This requires idx to be in the [0, num_inputs) range. If the relax is
329	  // successful and the new shape differs from the old one, store the new
330	  // shape and return true. Return false otherwise.
331	  bool RelaxInput(int idx, ShapeHandle shape) {
332	    ShapeHandle new_shape;
333	    Relax(inputs_[idx], shape, &new_shape);
334	    if (inputs_[idx].SameHandle(new_shape)) {
335	      return false;
336	    }
337	    inputs_[idx] = new_shape;
338	    return true;
339	  }
340	
341	  void SetInput(int idx, ShapeHandle shape) { inputs_[idx] = shape; }
342	
343	  ShapeHandle input(int64_t idx) const { return inputs_[idx]; }
344	  absl::Status input(absl::string_view input_name,
