417	  // idx can be negative for an offset from end of dimensions.
418	  // idx must be in the range [-1 * s.rank, s.rank).
419	  DimensionHandle Dim(ShapeHandle s, int64_t idx) {
420	    if (!s.Handle() || s->rank_ == kUnknownRank) {
